<form method="GET" class="panel p-4 md:p-5 mb-5"><div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-3"><div><label class="text-xs font-semibold muted">Attendance Date</label><input type="date" name="date" value="<?php echo e($date); ?>" class="field mt-1"></div><div><label class="text-xs font-semibold muted">Technology</label><select name="technology" class="field mt-1"><option value="">All Technologies</option><?php $__currentLoopData = $technologies; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $v): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(request('technology')==$v): echo 'selected'; endif; ?>><?php echo e($v); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div><label class="text-xs font-semibold muted">Semester</label><select name="semester" class="field mt-1"><option value="">All Semesters</option><?php $__currentLoopData = $semesters; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $v): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(request('semester')==$v): echo 'selected'; endif; ?>><?php echo e($v); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div><label class="text-xs font-semibold muted">Session</label><select name="session" class="field mt-1"><option value="">All Sessions</option><?php $__currentLoopData = $sessions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $v): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(request('session')==$v): echo 'selected'; endif; ?>><?php echo e($v); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div></div><div class="flex gap-2 mt-4"><button class="btn btn-primary">Load Students</button><a href="<?php echo e(route('attendance.index')); ?>" class="btn border">Reset</a></div></form>
<form method="POST" action="<?php echo e(route('attendance.store')); ?>" class="panel overflow-hidden"><?php echo csrf_field(); ?><input type="hidden" name="attendance_date" value="<?php echo e($date); ?>"><div class="p-4 md:p-5 border-b flex flex-wrap justify-between items-center gap-3"><div><div class="font-bold text-lg">Student List <span class="text-blue-700">(<?php echo e($students->count()); ?>)</span></div><div class="text-xs muted"><?php echo e(request('technology')?:'All Technologies'); ?> · <?php echo e(request('semester')?:'All Semesters'); ?> · <?php echo e(\Carbon\Carbon::parse($date)->format('d M Y')); ?></div></div><input id="studentSearch" class="field max-w-xs" placeholder="Search ID or student name..."></div>
