<div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-white text-slate-500"><tr><th class="p-3 text-left">Student</th><th class="p-3 text-left">Technology / Semester</th><th class="p-3 text-left">Session</th><th class="p-3 text-left min-w-[160px]">Attendance Status</th></tr></thead><tbody id="attendanceRows"><?php $__empty_1 = true; $__currentLoopData = $students; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $s): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><?php ($current=$records[$s->id]->status??'Present'); ?><tr class="border-t hover:bg-slate-50 attendance-row"><td class="p-3"><div class="flex items-center gap-3"><img src="<?php echo e($s->profile_photo_url?:'https://ui-avatars.com/api/?name='.urlencode($s->name).'&background=e0e7ff&color=1d4ed8'); ?>" class="w-9 h-9 rounded-full object-cover"><div><div class="font-semibold"><?php echo e($s->name); ?></div><div class="text-xs muted"><?php echo e($s->student_id); ?></div></div></div></td><td class="p-3"><?php echo e($s->technology); ?><div class="text-xs muted"><?php echo e($s->semester); ?> Semester</div></td><td class="p-3"><?php echo e($s->session?:'—'); ?></td><td class="p-3"><select name="attendance[<?php echo e($s->id); ?>]" class="field attendance-select py-2" onchange="updateCounts()"><option value="Present" <?php if($current=='Present'): echo 'selected'; endif; ?>>Present</option><option value="Absent" <?php if($current=='Absent'): echo 'selected'; endif; ?>>Absent</option><option value="Late" <?php if($current=='Late'): echo 'selected'; endif; ?>>Late</option><option value="Leave" <?php if($current=='Leave'): echo 'selected'; endif; ?>>Leave</option></select></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="4" class="p-10 text-center muted">এই Filter-এ কোনো Active Student পাওয়া যায়নি। Technology ও Semester নির্বাচন করে Load Students চাপুন।</td></tr><?php endif; ?></tbody></table></div><div class="p-4 border-t flex flex-wrap justify-between items-center gap-3"><span class="text-xs muted">Save করার পর একই তারিখে আবার edit করা যাবে।</span><button class="btn btn-primary" <?php if($students->isEmpty()): ?> disabled <?php endif; ?>>✓ Save Attendance (<?php echo e($students->count()); ?>)</button></div></form>
<script>function setAll(v){document.querySelectorAll('.attendance-select').forEach(x=>x.value=v);updateCounts()}function updateCounts(){const c={Present:0,Absent:0,Late:0,Leave:0};document.querySelectorAll('.attendance-select').forEach(x=>c[x.value]++);document.getElementById('countSummary').textContent=`Present ${c.Present} · Absent ${c.Absent} · Late ${c.Late} · Leave ${c.Leave}`}document.getElementById('studentSearch').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.attendance-row').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')});updateCounts();</script>
